/* From Uiverse.io by sujeet-12 - Tags: checkbox, fun-check, circle-checkbox */
/* Hide the default checkbox */
.__UIV_SCOPE__ .container input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
  height: 0;
  width: 0;
}

.__UIV_SCOPE__ .container {
  display: block;
  position: relative;
  cursor: pointer;
  font-size: 20px;
  user-select: none;
  animation: jello-horizontal 0.9s both;
}

.__UIV_SCOPE__ .checkmark:hover {
  animation: jello-horizontal 0.9s both;
}

/* Create a custom checkbox */
.__UIV_SCOPE__ .checkmark {
  position: relative;
  top: 0;
  left: 0;
  height: 1.3em;
  width: 1.3em;
  border-radius: 50%;
  background-color: #eee;
}

/* When the checkbox is checked, add a blue background */
.__UIV_SCOPE__ .container input:checked ~ .checkmark {
  background-color: royalblue;
}

/* Create the checkmark/indicator (hidden when not checked) */
.__UIV_SCOPE__ .checkmark:after {
  content: "";
  position: absolute;
  display: none;
}

/* Show the checkmark when checked */
.__UIV_SCOPE__ .container input:checked ~ .checkmark:after {
  display: block;
}

/* Style the checkmark/indicator */
.__UIV_SCOPE__ .container .checkmark:after {
  left: 0.45em;
  top: 0.25em;
  width: 0.25em;
  height: 0.5em;
  border: solid white;
  border-width: 0 0.15em 0.15em 0;
  transform: rotate(45deg);
}

@keyframes jello-horizontal {
  0% {
    -webkit-transform: scale3d(1, 1, 1);
    transform: scale3d(1, 1, 1);
  }

  30% {
    -webkit-transform: scale3d(1.25, 0.75, 1);
    transform: scale3d(1.25, 0.75, 1);
  }

  40% {
    -webkit-transform: scale3d(0.75, 1.25, 1);
    transform: scale3d(0.75, 1.25, 1);
  }

  50% {
    -webkit-transform: scale3d(1.15, 0.85, 1);
    transform: scale3d(1.15, 0.85, 1);
  }

  65% {
    -webkit-transform: scale3d(0.95, 1.05, 1);
    transform: scale3d(0.95, 1.05, 1);
  }

  75% {
    -webkit-transform: scale3d(1.05, 0.95, 1);
    transform: scale3d(1.05, 0.95, 1);
  }

  100% {
    -webkit-transform: scale3d(1, 1, 1);
    transform: scale3d(1, 1, 1);
  }
}
